  "marker": "TASK_COMPLETE",
  "answer": {
    "summary": "Tesla began reporting under the ASC 606‑specific concept RevenueFromContractWithCustomerExcludingAssessedTax in FY 2018 while continuing to tag the legacy Revenues concept for backward compatibility, resulting in duplicate tagging (some accurate, some erroneous). Prior to 2018 only the legacy concept exists; from 2018 onward either concept appears, but the ASC 606 concept is the preferred post‑adoption measure.",
    "claims": [
      {
        "text": "For fiscal years 2011‑2017 Tesla has facts only under the Revenues concept.",
        "evidence": ["E-713c42"]
      },
      {
        "text": "Starting in fiscal year 2018 Tesla files contain both concepts within the same accession_number (e.g., 2018 Q1, Q2, Q3, FY and 2023 Q3).",
        "evidence": ["E-b44e1f", "E-12deec"]
      },
      {
        "text": "In some filings the two concepts report identical values (e.g., accession 0001564590-18-011086 shows 3408751000 for both concepts), indicating duplicate tagging of the same fact.",
        "evidence": ["E-12deec"]
      },
      {
        "text": "In other filings the values differ (e.g., same accession shows Revenues 2696270000 versus RevenueFromContract... 3408751000), suggesting measurement differences or tagging errors.",
        "evidence": ["E-12deec"]
      }
    ],
    "inferences": [
      {
        "text": "The post‑2018 appearance of both concepts aligns with Tesla’s adoption of ASC 606 effective FY 2018, retaining the legacy concept for comparability.",
        "basis": ["claims 1", "claims 2"]
      },
      {
        "text": "Duplicate tagging of identical values under both concepts is a data‑artifact (filers mistakenly applied both tags) rather than an intentional separate measurement.",
        "basis": ["claims 3"]
      }
    ],
    "hypothesis_verdicts": [
      {
        "id": "H-94e4c0",
        "status": "refuted",
        "evidence": ["E-b44e1f", "E-12deec"],
        "why": "Both concepts appear within the same accession (same filing), not just across different filing types."
      },
      {
        "id": "H-8ea727",
        "status": "supported",
        "evidence": ["E-713c42", "E-b44e1f", "E-12deec"],
        "why": "New concept appears only from 2018 onward, consistent with ASC 606 adoption; legacy concept retained for comparability."
      },
      {
        "id": "H-15e299",
        "status": "supported",
        "evidence": ["E-b44e1f", "E-12deec"],
        "why": "Same accession_number tags both concepts, sometimes with identical values, indicating duplicate tagging."
      },
      {
        "id": "H-cea464",
        "status": "refuted",
        "evidence": ["E-12deec"],
        "why": "Values are not consistently different (some match, some differ), so the concepts do not represent a systematic tax‑exclusion distinction."
      },
      {
        "id": "H-f5a54e",
        "status": "supported",
        "evidence": ["E-713c42"],
        "why": "RevenueFromContractWithCustomerExcludingAssessedTax has zero facts before 2018 and appears after, indicating a taxonomy coverage gap."
      }
    ]
  },
  "carryover": {
    "COMPLETED": "Determined Tesla's revenue concept usage across years and reason for dual concepts.",
    "REMAINING": "-",
    "DECISIONS": "-",
    "CONTEXT": "Evidence shows pre‑2018 only Revenues concept; post‑2018 both concepts appear within same filings, with duplicate tagging and ASC 606 adoption explaining the pattern."
  }
}
